'use client'
/**
 * Landing — "The Company That Runs Itself." The approved retro/editorial redesign, ported verbatim from
 * the design preview. Self-contained: fonts via <link>, styles via <style>, markup via
 * dangerouslySetInnerHTML, reveal-on-scroll wired in useEffect. The previous landing (HireStory) is kept
 * at ./hire/HireStory for rollback — not deleted. Hero video lives at /public/hero.mp4 (compressed).
 */
import { useEffect } from 'react'

const CSS = "\n  :root{\n    --paper:#e9e1cf; --paper-2:#e2d9c2; --card:#f4efe1; --white:#f8f3e7;\n    --ink:#22281b; --ink-soft:#585d47; --fog:#8b8a72; --line:#cfc4a9; --hair:#dcd2ba;\n    --forest:#141d15; --forest-2:#1b2a1d; --forest-line:rgba(255,90,44,.18); --forest-hair:rgba(238,242,230,.1);\n    --lime:#ff5a2c; --lime-deep:#ef4a1e; --rust:#c1663a;\n    --sans:'General Sans',system-ui,-apple-system,'Segoe UI',Arial,sans-serif;\n    --serif:'Instrument Serif','Iowan Old Style',Georgia,serif;\n    --mono:'Space Mono',ui-monospace,Menlo,monospace;\n  }\n  *{box-sizing:border-box}\n  body{margin:0;background:var(--paper);color:var(--ink);font-family:var(--sans);-webkit-font-smoothing:antialiased;line-height:1.5;overflow-x:hidden}\n  ::selection{background:var(--lime);color:#fff}\n  a{color:inherit;text-decoration:none}\n  h1,h2,h3{margin:0;font-weight:700;letter-spacing:-.035em;text-wrap:balance;line-height:1}\n  p{margin:0}\n  .shell{max-width:1160px;margin:0 auto;padding:0 26px}\n  .grain{position:fixed;inset:0;z-index:9998;pointer-events:none;opacity:.09;mix-blend-mode:multiply;\n    background-image:url(\"data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='140' height='140'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='0.85' numOctaves='2' stitchTiles='stitch'/><feColorMatrix type='saturate' values='0'/></filter><rect width='100%25' height='100%25' filter='url(%23n)'/></svg>\")}\n  .scan{position:fixed;inset:0;z-index:9997;pointer-events:none;opacity:.28;background:repeating-linear-gradient(to bottom,rgba(0,0,0,.05) 0 1px,transparent 1px 3px)}\n\n  .btn-lime{background:var(--lime);color:#fff;padding:15px 28px;border-radius:2px;font-weight:700;font-size:15.5px;display:inline-flex;align-items:center;gap:8px;transition:transform .15s;border:1.5px solid var(--forest)}\n  .btn-lime:hover{transform:translateY(-2px)}\n  .btn-line{color:#fff;padding:15px 22px;border-radius:2px;font-weight:600;font-size:15px;border:1.5px solid rgba(255,255,255,.4);display:inline-flex;align-items:center;gap:8px}\n  .btn-line:hover{border-color:#fff}\n\n  /* nav */\n  .nav{position:absolute;top:0;left:0;right:0;z-index:50}\n  .nav-in{max-width:1160px;margin:0 auto;padding:20px 26px;display:flex;align-items:center;justify-content:space-between}\n  .brand{display:flex;align-items:center}\n  .brandimg{height:clamp(22px,2.4vw,28px);width:auto;display:block}\n  .brand .mk{width:28px;height:28px;border-radius:3px;background:var(--lime);color:#fff;display:grid;place-items:center;font-weight:700;font-size:15px;font-family:var(--sans)}\n  .nav-right{display:flex;align-items:center;gap:18px}\n  .nav .navlogin{color:#f8f3e7;font-weight:700;font-size:12px;text-transform:uppercase;font-family:var(--mono);letter-spacing:.05em;opacity:.85;transition:opacity .2s}\n  .nav .navlogin:hover{opacity:1}\n  .nav .cta{background:var(--lime);color:#fff;padding:9px 16px;border-radius:2px;font-weight:700;font-size:12px;text-transform:uppercase;font-family:var(--mono);letter-spacing:.05em}\n\n  /* HERO — cinema. video, huge type, almost no UI. */\n  .hero{position:relative;min-height:94vh;display:flex;align-items:center;overflow:hidden;color:#fff;background:#0c120d}\n  .hero-video{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;z-index:1;filter:grayscale(.35) contrast(1.08) sepia(.12)}\n  .hero-scrim{position:absolute;inset:0;z-index:2;background:linear-gradient(90deg,rgba(8,13,9,.85),rgba(8,13,9,.5) 46%,rgba(8,13,9,.14) 74%),linear-gradient(180deg,rgba(8,13,9,.45),rgba(8,13,9,.14) 30%,rgba(8,13,9,.72))}\n  .hero-scan{position:absolute;inset:0;z-index:3;pointer-events:none;opacity:.5;background:repeating-linear-gradient(to bottom,rgba(0,0,0,.1) 0 1px,transparent 1px 4px)}\n  .hero-in{position:relative;z-index:4;width:100%}\n  .kick{font-family:var(--mono);font-size:12px;letter-spacing:.24em;text-transform:uppercase;color:var(--lime);font-weight:700;display:flex;align-items:center;gap:10px}\n  .kick::before{content:\"●\";color:var(--rust);animation:rec 1.6s steps(1) infinite}\n  @keyframes rec{50%{opacity:.25}}\n  .hero h1{color:#fff;font-size:clamp(46px,8.4vw,108px);letter-spacing:-.05em;margin:22px 0 0;line-height:.94;max-width:12ch}\n  .hero h1 em{font-style:normal;color:var(--lime)}\n  .hero .sub{font-size:clamp(16px,1.9vw,20px);color:#d7ddd0;margin-top:24px;max-width:44ch;line-height:1.5}\n  .hero .sub b{color:#fff;font-weight:700}\n  .hero .cta-row{display:flex;gap:12px;margin-top:34px;flex-wrap:wrap}\n  .hero .tc{position:absolute;right:0;bottom:6px;z-index:4;font-family:var(--mono);font-size:11px;color:rgba(255,255,255,.55);letter-spacing:.08em}\n\n  /* big statement band under the hero */\n  .bigstatement{background:#ef4a1e;color:#fff;padding:clamp(78px,10vw,126px) 0 clamp(48px,6vw,72px)}\n  .bigstatement p{color:#fdf3ec;font-size:clamp(28px,4.5vw,60px);font-weight:600;letter-spacing:-.03em;line-height:1.1;max-width:20ch}\n  .bigstatement p b{font-weight:600;color:#ffe4d8}\n  .bs-item{display:flex;align-items:flex-start;gap:clamp(18px,3vw,34px);margin-top:clamp(64px,9vw,120px)}\n  @media(max-width:600px){.bs-item{flex-direction:column;gap:14px}}\n  .bs-no{font-family:var(--sans);font-size:clamp(24px,3vw,40px);font-weight:600;color:#fff;border:2px solid rgba(255,255,255,.55);border-radius:100px;padding:4px 20px;line-height:1.15;flex:0 0 auto}\n  .bs-h{font-size:clamp(28px,4vw,52px);font-weight:600;color:#fff;letter-spacing:-.03em;line-height:1.08;max-width:20ch}\n  /* animated \"learning\" mockup — big, responsive, SCROLL-SCRUBBED via --sp (0→1) set by JS */\n  .learnviz{margin:clamp(46px,6vw,84px) auto 0;background:#12180f;border-radius:16px;overflow:hidden;width:100%;max-width:1080px;box-shadow:0 54px 120px -46px rgba(0,0,0,.62);transform:rotate(-.4deg)}\n  .lv-top{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:clamp(14px,1.7vw,20px) clamp(16px,2.2vw,28px);border-bottom:1px solid rgba(255,255,255,.07)}\n  .lv-src{display:flex;align-items:center;gap:10px;font-family:var(--mono);font-size:clamp(12px,1.3vw,14px);color:#cdd8c4;letter-spacing:.05em;min-width:0}\n  .lv-src .d{width:10px;height:10px;border-radius:50%;background:var(--lime);flex:0 0 auto;animation:lvblip 2.4s ease-in-out infinite}\n  @keyframes lvblip{0%,100%{box-shadow:0 0 0 0 rgba(255,90,44,.55)}50%{box-shadow:0 0 0 7px rgba(255,90,44,0)}}\n  .lv-tag{font-family:var(--mono);font-size:clamp(10px,1.1vw,12px);letter-spacing:.12em;text-transform:uppercase;color:#fff;background:var(--lime);padding:6px 13px;border-radius:100px;font-weight:700;opacity:0;transition:opacity .3s ease;white-space:nowrap;flex:0 0 auto}\n  .lv-body{padding:clamp(20px,3vw,42px) clamp(18px,2.6vw,34px) clamp(8px,1.4vw,16px)}\n  .lv-h{font-family:var(--mono);font-size:clamp(11px,1.2vw,13px);color:#8fa088;letter-spacing:.1em;text-transform:uppercase;margin-bottom:clamp(12px,1.8vw,20px)}\n  .lv-line{font-size:clamp(15px,2vw,22px);color:#b7c2ad;padding:clamp(10px,1.5vw,16px) clamp(12px,1.6vw,18px);line-height:1.4;border-radius:8px}\n  .lv-key{position:relative;overflow:hidden;color:#fff;font-weight:600;isolation:isolate}\n  .lv-key::before{content:\"\";position:absolute;inset:0;background:var(--lime);transform-origin:left;transform:scaleX(var(--sp,0));z-index:-1;transition:transform .1s linear}\n  .lv-key .kt{transition:color .18s ease}\n  .lv-logos{display:flex;flex-wrap:wrap;gap:clamp(12px,1.6vw,18px);justify-content:center;padding:clamp(16px,2.2vw,28px);border-top:1px solid rgba(255,255,255,.07);margin-top:clamp(12px,1.6vw,20px)}\n  .lv-logos .lg{width:clamp(40px,4.6vw,52px);height:clamp(40px,4.6vw,52px);border-radius:11px;background:#fff;display:grid;place-items:center;opacity:.5;cursor:pointer;transition:opacity .2s ease,transform .2s ease,box-shadow .2s ease}\n  .lv-logos .lg:hover{opacity:.85;transform:translateY(-2px)}\n  .lv-logos .lg.active{opacity:1;transform:translateY(-2px);box-shadow:0 0 0 3px rgba(255,90,44,.8)}\n  .lv-hint{text-align:center;font:600 9.5px/1 var(--mono);letter-spacing:.14em;text-transform:uppercase;color:#8fa088;padding:14px 0 2px}\n  .lv-logos .lg svg{width:60%;height:60%}\n  @media(max-width:640px){.learnviz{transform:none;border-radius:12px}}\n  @media(prefers-reduced-motion:reduce){.lv-key::before{transform:scaleX(1)}.lv-key .kt{color:#0c120d}.lv-tag{opacity:1}.lv-logos .lg{opacity:.85}.lv-src .d{animation:none}}\n\n  /* type-led section openers */\n  .opener{font-family:var(--serif);font-weight:400;letter-spacing:-.015em;line-height:1;font-size:clamp(40px,6.4vw,86px)}\n  .opener em{font-style:italic;color:var(--rust)}\n  .mono-eyebrow{font-family:var(--mono);font-size:12px;letter-spacing:.16em;text-transform:uppercase;font-weight:700;color:var(--rust)}\n  /* Entrance runs from CSS on load (no JS gate) so section text never waits for React to hydrate.\n     .in is still added by the IntersectionObserver but is now just a harmless end-state alias. */\n  .rv{animation:rvIn .7s cubic-bezier(.2,.7,.2,1) both}\n  .rv.in{opacity:1;transform:none}\n  .rv.d1{animation-delay:.1s}.rv.d2{animation-delay:.2s}\n  @keyframes rvIn{from{opacity:0;transform:translateY(24px)}to{opacity:1;transform:none}}\n  @media(prefers-reduced-motion:reduce){.rv{animation:none}}\n\n  /* ============ 02 · BRAIN — one large, dense, real interface ============ */\n  .brainsec{padding:110px 0 0;background:var(--paper)}\n  .brainsec .lede{margin-top:18px;font-size:clamp(16px,1.9vw,20px);color:var(--ink-soft);max-width:46ch}\n  .brain-lay{display:grid;grid-template-columns:.62fr 1.38fr;gap:44px;align-items:start;margin-top:56px}\n  @media(max-width:920px){.brain-lay{grid-template-columns:1fr;gap:28px}}\n  .brain-notes{padding-top:26px}\n  .brain-notes .b{border-top:1px solid var(--line);padding:18px 0 20px}\n  .brain-notes .b .k{font-family:var(--mono);font-size:11px;letter-spacing:.12em;color:var(--rust);text-transform:uppercase;font-weight:700}\n  .brain-notes .b h3{font-size:clamp(20px,2.2vw,27px);margin-top:8px;letter-spacing:-.03em}\n  .brain-notes .b p{font-size:14.5px;color:var(--ink-soft);margin-top:8px;max-width:34ch}\n  .brainui-crop{position:relative;margin-right:calc(-1 * max(26px, (100vw - 1160px)/2 + 26px));overflow:hidden}\n  .brainui{background:var(--white);border:1px solid var(--ink);border-right:none;font-size:13.5px;box-shadow:14px 18px 0 rgba(34,40,27,.12)}\n  .bu-head{display:flex;align-items:baseline;justify-content:space-between;gap:14px;padding:16px 22px;border-bottom:1px solid var(--ink);flex-wrap:wrap}\n  .bu-head .t{font-family:var(--mono);font-weight:700;letter-spacing:.1em;font-size:13px}\n  .bu-head .m{font-family:var(--mono);font-size:11px;color:var(--fog)}\n  .bu-cols{display:grid;grid-template-columns:1fr 1fr 1.15fr}\n  @media(max-width:720px){.bu-cols{grid-template-columns:1fr}}\n  .bu-col{padding:18px 22px;border-right:1px solid var(--hair);min-width:0}\n  .bu-col:last-child{border-right:none}\n  .bu-col .h{font-family:var(--mono);font-size:10.5px;letter-spacing:.14em;text-transform:uppercase;color:var(--fog);font-weight:700;padding-bottom:9px;border-bottom:1px solid var(--hair);margin-bottom:11px}\n  .bu-row{padding:6px 0;font-size:13.5px;color:var(--ink);border-bottom:1px dotted var(--hair)}\n  .bu-row:last-child{border-bottom:none}\n  .bu-row .sub{color:var(--fog);font-size:12px}\n  .bu-stat{display:flex;justify-content:space-between;gap:10px;font-variant-numeric:tabular-nums}\n  .bu-stat b{font-weight:700}\n  .bu-learn{margin:0 22px 20px;border:1px solid var(--ink);background:var(--lime);padding:13px 16px}\n  .bu-learn .k{font-family:var(--mono);font-size:10px;letter-spacing:.14em;text-transform:uppercase;font-weight:700}\n  .bu-learn .v{font-size:15px;font-weight:600;margin-top:4px;line-height:1.35}\n\n  /* ============ MEMORY — a timeline/stream, text-heavy ============ */\n  .memsec{padding:110px 0;background:var(--paper)}\n  .memlay{display:grid;grid-template-columns:1.05fr .95fr;gap:56px;align-items:start;margin-top:52px}\n  @media(max-width:920px){.memlay{grid-template-columns:1fr;gap:26px}}\n  .stream{border-left:1px solid var(--ink);padding-left:0;font-size:14px}\n  .mem{display:grid;grid-template-columns:74px 1fr;gap:0;border-bottom:1px solid var(--hair)}\n  .mem:last-child{border-bottom:none}\n  .mem .d{font-family:var(--mono);font-size:11px;letter-spacing:.08em;color:var(--fog);padding:14px 0 14px 16px;border-right:1px solid var(--hair)}\n  .mem .c{padding:14px 0 14px 18px}\n  .mem .tag{font-family:var(--mono);font-size:10px;letter-spacing:.12em;text-transform:uppercase;font-weight:700;color:var(--rust)}\n  .mem .tag.dec{color:var(--forest);background:var(--lime);padding:1px 6px}\n  .mem .tx{font-size:14.5px;margin-top:3px;line-height:1.45}\n  .memcopy h3{font-size:clamp(22px,2.6vw,32px);letter-spacing:-.03em;margin-top:10px}\n  .memcopy p{color:var(--ink-soft);font-size:15.5px;margin-top:12px;max-width:38ch;line-height:1.55}\n  .memcopy .big{font-family:var(--serif);font-size:clamp(26px,3.4vw,44px);line-height:1.05;letter-spacing:-.015em;margin-top:6px}\n  .memcopy .big em{font-style:italic;color:var(--rust)}\n\n  /* ============ 03 · WORK — dark, artifacts through the pipeline ============ */\n  .worksec{background:var(--forest);color:#eef2e6;padding:110px 0}\n  .worksec .mono-eyebrow{color:var(--lime)}\n  .worksec .opener{color:#fff}\n  .worksec .opener em{color:var(--lime)}\n  .pipe{max-width:760px;margin:60px auto 0;position:relative}\n  .pipe::before{content:\"\";position:absolute;left:26px;top:10px;bottom:10px;width:1px;background:var(--forest-line)}\n  .pipe::after{content:\"\";position:absolute;left:26px;top:10px;width:1px;height:calc(var(--wp,0) * (100% - 20px));background:var(--lime);box-shadow:0 0 10px rgba(255,90,44,.5);transition:height .12s linear;z-index:0}\n  .job{position:relative;display:grid;grid-template-columns:54px 130px 1fr;gap:0 18px;padding:20px 0;border-bottom:1px solid var(--forest-hair);align-items:start;opacity:.2;transform:translateY(14px);transition:opacity .35s ease,transform .35s ease}\n  @media(max-width:640px){.job{grid-template-columns:54px 1fr}.job .dept{grid-column:2}.job .art{grid-column:2}}\n  .job .node{position:relative;z-index:1;width:13px;height:13px;border-radius:50%;background:var(--forest);border:2px solid var(--lime);margin-left:20px;margin-top:4px;transition:background .3s ease,box-shadow .3s ease}\n  .job.lit .node{background:var(--lime);box-shadow:0 0 0 6px rgba(255,90,44,.16)}\n  .job .dept{font-family:var(--mono);font-size:11px;letter-spacing:.14em;text-transform:uppercase;color:var(--lime);font-weight:700;padding-top:2px}\n  .job .art{min-width:0}\n  .job .say{font-size:15.5px;color:#e7ecdf;line-height:1.45}\n  .job .say b{color:#fff}\n  .artifact{margin-top:10px;background:var(--card);color:var(--ink);border:1px solid #0a0f0b;font-size:13px;max-width:480px}\n  .artifact .bar{display:flex;justify-content:space-between;gap:10px;font-family:var(--mono);font-size:10px;letter-spacing:.1em;text-transform:uppercase;padding:7px 12px;border-bottom:1px solid var(--hair);color:var(--fog)}\n  .artifact .pad{padding:11px 12px}\n  .art-ad{display:grid;grid-template-columns:96px 1fr}\n  .art-ad .img{background:radial-gradient(120% 100% at 30% 20%,#fbe6d6,#eab48f 70%,#d78a5f);display:grid;place-items:center;min-height:96px}\n  .art-ad .img i{display:block;width:30px;height:52px;border-radius:7px 7px 9px 9px;background:linear-gradient(180deg,rgba(255,255,255,.95),rgba(255,255,255,.75));box-shadow:0 6px 14px -6px rgba(23,37,28,.4)}\n  .art-ad .cp{padding:10px 12px}\n  .art-ad .h{font-weight:700;font-size:13.5px}\n  .art-ad .s{color:var(--ink-soft);font-size:12px;margin-top:3px}\n  .art-ad .cta2{display:inline-block;margin-top:8px;font-family:var(--mono);font-size:10px;letter-spacing:.08em;border:1px solid var(--ink);padding:3px 8px}\n  .kv{display:flex;justify-content:space-between;gap:10px;padding:5px 0;border-bottom:1px dotted var(--hair);font-variant-numeric:tabular-nums}\n  .kv:last-child{border-bottom:none}\n  .kv .k{color:var(--ink-soft)}\n  .kv b{font-weight:700}\n  .ok{display:inline-block;background:var(--lime);border:1px solid var(--ink);font-family:var(--mono);font-size:10px;letter-spacing:.08em;text-transform:uppercase;font-weight:700;padding:3px 8px}\n  .chatline{padding:7px 0;border-bottom:1px dotted var(--hair);font-size:13px}\n  .chatline:last-child{border-bottom:none}\n  .chatline .who{font-family:var(--mono);font-size:10px;color:var(--fog);text-transform:uppercase;letter-spacing:.08em}\n  .tilt-l{transform:rotate(-1.1deg)}\n  .tilt-r{transform:rotate(.8deg)}\n\n  /* ============ 04 · AGREEMENT (unchanged content) ============ */\n  .hire{background:#ef4a1e;color:#fff;padding:clamp(34px,4.5vw,54px) 0 clamp(78px,10vw,120px);text-align:center}\n  .p-lead{font-family:var(--sans);font-weight:700;font-size:clamp(30px,5.4vw,60px);letter-spacing:-.035em;max-width:20ch;margin:0 auto clamp(36px,5vw,54px);line-height:1.02;color:#fff;text-align:center}\n  .p-lead em{font-family:var(--serif);font-style:italic;font-weight:400;color:#fff}\n  .paper{max-width:600px;margin:0 auto;background:var(--white);color:var(--ink);border:1px solid rgba(20,29,21,.25);padding:36px 38px;text-align:left;box-shadow:16px 18px 0 rgba(20,29,21,.22)}\n  @media(max-width:560px){.paper{padding:26px 22px}}\n  .p-eyebrow{font-family:var(--mono);font-size:10.5px;letter-spacing:.14em;text-transform:uppercase;color:var(--rust);font-weight:700}\n  .p-title{font-family:var(--serif);font-size:40px;letter-spacing:-.01em;margin:6px 0 3px;color:var(--ink)}\n  .p-date{font-family:var(--mono);font-size:11px;color:var(--fog);margin-bottom:18px}\n  .p-row{display:flex;justify-content:space-between;gap:16px;padding:11px 0;border-bottom:1px solid var(--hair);font-size:14.5px}\n  .p-row span{color:var(--ink-soft)}.p-row b{color:var(--ink);font-weight:700;text-align:right}\n  .p-resp{padding:13px 0;border-bottom:1px solid var(--hair)}\n  .p-resp .lbl{color:var(--ink-soft);font-size:14.5px;margin-bottom:9px}\n  .p-resp ul{margin:0;padding:0;list-style:none;display:grid;grid-template-columns:1fr 1fr;gap:6px 16px}\n  @media(max-width:480px){.p-resp ul{grid-template-columns:1fr}}\n  .p-resp li{font-size:13.5px;color:var(--ink);font-weight:600;display:flex;align-items:center;gap:8px}\n  .p-resp li::before{content:\"✓\";color:var(--rust);font-weight:700}\n  .p-note{font-size:13.5px;color:var(--ink-soft);line-height:1.6;margin:18px 0 4px}.p-note b{color:var(--ink)}\n  .sigs{display:flex;gap:28px;margin:24px 0 6px}.sig{flex:1}\n  .sig .line{border-bottom:1.5px solid var(--ink);padding-bottom:6px;font-family:var(--serif);font-size:26px;min-height:36px}\n  .sig .line input{border:none;outline:none;background:transparent;font-family:var(--serif);font-size:22px;width:100%;color:var(--ink)}\n  .sig .who{font-family:var(--mono);font-size:9.5px;letter-spacing:.06em;text-transform:uppercase;color:var(--fog);margin-top:7px}\n  .hirebtn{display:block;width:100%;margin-top:22px;background:var(--forest);color:#fff;border:none;border-radius:2px;padding:16px;font-size:15.5px;font-weight:700;font-family:inherit;cursor:pointer;text-align:center;text-decoration:none;box-sizing:border-box}\n  .p-fine{text-align:center;font-size:11.5px;color:var(--fog);margin-top:14px;font-family:var(--mono)}\n\n  .footer{padding:44px 0 40px;text-align:center;background:#ef4a1e;border-top:1px solid rgba(255,255,255,.22)}\n  .foot-meta{font-size:11.5px;color:#fde3d9;font-family:var(--mono);letter-spacing:.06em}\n  /* ── LEARNING → ACTION : the transformation (Hyper-style scrub, Selfmade context) — orange band, dark stage ── */\n  .actsec{background:#ef4a1e;color:#fff;padding:clamp(34px,4.5vw,56px) 0 clamp(72px,9vw,110px);position:relative;overflow:hidden}\n  .actsec .bs-item{margin-top:0}\n  .actsec .bs-h em{font-family:var(--serif);font-style:italic;font-weight:400;color:#fff}\n  .act-sub{margin-top:clamp(22px,3vw,34px);max-width:56ch;color:#fdf3ec;font-size:clamp(14.5px,1.7vw,18px);line-height:1.5;font-weight:500}\n  .act-panel{position:relative;margin-top:clamp(40px,6vw,64px);background:#101a12;border:1px solid rgba(255,255,255,.09);\n    border-radius:16px;padding:clamp(22px,4vw,48px);box-shadow:0 46px 90px -46px rgba(0,0,0,.55)}\n  .actstage{position:relative;display:grid;\n    grid-template-columns:minmax(200px,.86fr) 60px minmax(320px,1.3fr);align-items:center;min-height:clamp(430px,50vw,520px)}\n\n  /* left — raw learnings drifting */\n  .act-in{position:relative;height:100%;min-height:480px}\n  .act-in .lbl{position:absolute;top:-6px;left:0;font:600 10.5px/1 var(--mono);letter-spacing:.14em;color:#7f8a76}\n  .chip{position:absolute;display:inline-flex;align-items:center;gap:8px;\n    background:rgba(238,242,230,.055);border:1px solid var(--forest-hair);color:#d3dac9;\n    font:500 12.5px/1.2 var(--sans);padding:9px 12px;border-radius:7px;white-space:nowrap;will-change:transform,opacity}\n  .chip .dot{width:7px;height:7px;border-radius:50%;background:var(--rust);flex:none;box-shadow:0 0 0 3px rgba(193,102,58,.16)}\n  .chip .mono{font-family:var(--mono);font-size:11px;color:#9fa892}\n  .chip.c1{top:5%;left:1%}.chip.c2{top:20%;left:33%}.chip.c3{top:37%;left:4%}\n  .chip.c4{top:54%;left:36%}.chip.c5{top:71%;left:8%}.chip.c6{top:87%;left:28%}\n\n  /* seam — the brain gate */\n  .act-seam{position:relative;height:100%;min-height:480px;display:flex;align-items:center;justify-content:center}\n  .act-seam::before{content:\"\";position:absolute;top:0;bottom:0;left:50%;width:1px;transform:translateX(-.5px);\n    background:repeating-linear-gradient(to bottom,var(--forest-line) 0 6px,transparent 6px 13px)}\n  .act-seam::after{content:\"\";position:absolute;left:50%;top:calc(5% + var(--ap,0) * 84%);width:9px;height:9px;border-radius:50%;\n    transform:translate(-50%,-50%);background:var(--lime);box-shadow:0 0 14px 4px rgba(255,90,44,.6);opacity:calc(.15 + var(--ap,0)*.85)}\n  .seam-mk{position:relative;z-index:2;width:46px;height:46px;border-radius:50%;display:grid;place-items:center;\n    background:var(--forest-2);border:1px solid var(--lime);color:var(--lime);font:400 20px var(--serif);\n    box-shadow:0 0 0 7px var(--forest),0 0 26px rgba(255,90,44,calc(.12 + var(--ap,0)*.55))}\n  .seam-mk span{font:600 8px/1 var(--mono);letter-spacing:.1em;position:absolute;bottom:-20px;color:#8b957e;white-space:nowrap}\n\n  /* right — the actions */\n  .act-out{position:relative;display:grid;gap:14px;grid-template-columns:.82fr 1fr;\n    grid-template-areas:\"rail rail\" \"res img\" \"vid fb\"}\n  .flowrail{grid-area:rail;display:flex;align-items:center;gap:7px;flex-wrap:wrap;margin-bottom:4px}\n  .flowrail .fr{display:inline-flex;align-items:center;gap:7px;font:600 11px/1 var(--sans);color:#e7efe0;background:rgba(238,242,230,.06);border:1px solid var(--forest-hair);padding:7px 12px 7px 7px;border-radius:100px}\n  .flowrail .fr b{width:18px;height:18px;border-radius:50%;background:var(--lime);color:#fff;display:grid;place-items:center;font:700 10px/1 var(--sans);flex:none}\n  .flowrail .ar{width:16px;height:2px;background:var(--forest-line);position:relative;flex:none}\n  .flowrail .ar::after{content:\"\";position:absolute;right:-1px;top:-3px;border:4px solid transparent;border-left-color:var(--forest-line)}\n  @media(max-width:560px){.flowrail .fr .lb{display:none}.flowrail{gap:5px}}\n  .act-card{background:var(--card);color:var(--ink);border:1px solid var(--line);border-radius:9px;overflow:hidden;\n    box-shadow:0 1px 0 rgba(0,0,0,.04);will-change:transform,opacity;opacity:.14;transform:translateY(18px) scale(.975);\n    transition:opacity .5s ease,transform .55s cubic-bezier(.4,0,.2,1),box-shadow .5s ease}\n  .chip{transition:transform .55s cubic-bezier(.4,0,.2,1),opacity .5s ease}\n  .act-card.lit{box-shadow:0 20px 44px -24px rgba(0,0,0,.6),0 0 0 1px rgba(255,90,44,.55)}\n  .ac1{grid-area:res}.ac2{grid-area:img}.ac3{grid-area:vid}.ac4{grid-area:fb}\n  .ac-bar .sn{display:inline-grid;place-items:center;width:15px;height:15px;border-radius:50%;background:var(--lime);color:#fff;font:700 9px/1 var(--sans);margin-right:6px;vertical-align:middle}\n  .ac-bar{display:flex;justify-content:space-between;align-items:center;background:var(--forest);color:#dfe6d8;\n    font:600 10px/1 var(--mono);letter-spacing:.1em;padding:9px 12px}\n  .ac-bar .st{color:var(--lime)}\n  .ac-body{padding:11px 13px}\n  .ac-kv{display:flex;justify-content:space-between;gap:12px;padding:6px 0;border-bottom:1px solid var(--hair);font-size:12.5px}\n  .ac-kv:last-child{border-bottom:0}.ac-kv .k{color:var(--ink-soft)}.ac-kv b{font-weight:600;text-align:right}\n  .ac-cap{padding:9px 13px;border-top:1px solid var(--hair);font-size:11.5px;color:var(--ink-soft)}\n  .ac-thumb{display:flex;align-items:center;gap:10px;margin-top:6px;padding-top:11px;border-top:1px solid var(--hair)}\n  .ac-thumb .ci{width:56px;height:36px;border-radius:5px;flex:none;position:relative;overflow:hidden;background:linear-gradient(135deg,#d9c3ae,#cfe0c4)}\n  .ac-thumb .ci::after{content:\"\";position:absolute;left:50%;bottom:-12%;width:24%;height:72%;transform:translateX(-50%);border-radius:44% 44% 46% 46%/60% 60% 40% 40%;background:linear-gradient(180deg,#fff,#eef4ea)}\n  .ac-thumb .tl{font:600 10.5px/1.35 var(--sans);color:var(--ink-soft)}\n  .ac-thumb .tl b{display:block;color:var(--ink);font-size:12px}\n  .ac-vars{display:grid;grid-template-columns:1fr 1fr 1fr;gap:7px;padding:9px 13px 3px}\n  .ac-vars .var{position:relative;border-radius:6px;overflow:hidden;border:1px solid var(--hair)}\n  .ac-vars .var i{display:block;aspect-ratio:1/1;background:linear-gradient(135deg,#e9d6c4,#d7e6c0 60%,#cfe0d8)}\n  .ac-vars .var span{position:absolute;left:4px;bottom:4px;font:700 8px/1 var(--mono);color:#14201a;background:rgba(255,255,255,.88);padding:3px 4px;border-radius:3px}\n  .ac-vars .var.win{border-color:var(--lime);box-shadow:0 0 0 1px var(--lime)}\n  .ac-vars .var em{position:absolute;right:4px;top:4px;font:700 7.5px/1 var(--sans);font-style:normal;color:#fff;background:var(--lime);padding:3px 5px;border-radius:3px}\n\n  /* generated image still */\n  .ac-shot{position:relative;aspect-ratio:16/10;overflow:hidden;\n    background:radial-gradient(130% 120% at 80% 0%,#ffe7cb,#f4cfa4 42%,#e6ad7d)}\n  .ac-shot .ad-cta{position:absolute;left:7%;bottom:11%;z-index:4;display:inline-flex;align-items:center;gap:5px;background:#14201a;color:#fff;font:700 10.5px/1 var(--sans);padding:8px 13px;border-radius:100px;box-shadow:0 7px 16px -8px rgba(0,0,0,.55)}\n  .ac-shot .badge{position:absolute;top:9px;right:9px;background:rgba(20,29,21,.82);color:#eaf3c9;z-index:4;\n    font:600 9px/1 var(--mono);letter-spacing:.08em;padding:5px 7px;border-radius:5px}\n  .ac-shot .swash{position:absolute;inset:0;z-index:3;background:linear-gradient(115deg,transparent 34%,rgba(255,255,255,.45) 48%,transparent 60%);\n    transform:translateX(calc(-40% + var(--ap,0)*160%))}\n  /* a real-looking serum-bottle creative (drawn in CSS) so cards read as finished ads, not placeholders */\n  .bottle{position:absolute;left:52%;bottom:7%;transform:translateX(-50%);width:19%;aspect-ratio:.5;z-index:2}\n  .bottle::after{content:\"\";position:absolute;left:-34%;right:-34%;bottom:-5%;height:9%;border-radius:50%;\n    background:radial-gradient(closest-side,rgba(0,0,0,.3),transparent)}\n  .bottle .cap{position:absolute;left:33%;right:33%;top:0;height:10%;border-radius:4px 4px 2px 2px;background:linear-gradient(180deg,#3a3a3a,#151515)}\n  .bottle .neck{position:absolute;left:38%;right:38%;top:9%;height:9%;background:linear-gradient(180deg,#eef2f3,#d4dcdf)}\n  .bottle .glass{position:absolute;left:0;right:0;top:17%;bottom:0;border-radius:11px 11px 13px 13px;overflow:hidden;\n    background:linear-gradient(104deg,rgba(255,255,255,.94),rgba(255,255,255,.5) 32%,rgba(255,255,255,.88));\n    box-shadow:0 16px 26px -12px rgba(0,0,0,.4),inset 0 0 0 1px rgba(0,0,0,.06)}\n  .bottle .glass::before{content:\"\";position:absolute;left:0;right:0;bottom:0;height:78%;background:linear-gradient(180deg,#f7d59b,#eba24a 30%,#e08f34)}\n  .bottle .glass::after{content:\"\";position:absolute;left:0;right:0;top:22%;height:3px;background:rgba(255,255,255,.55)}\n  .bottle .label{position:absolute;left:16%;right:16%;top:42%;bottom:15%;background:rgba(255,255,255,.96);border-radius:2px;z-index:2;\n    display:flex;flex-direction:column;justify-content:center;gap:3px;padding:0 5px}\n  .bottle .label i{height:2px;background:#c9713e;border-radius:2px}\n  .bottle .label i:nth-child(1){width:56%;height:2.5px;background:#14201a}\n  .bottle .label i:nth-child(3){width:74%}\n  .bottle .shine{position:absolute;left:15%;top:22%;width:6%;bottom:15%;border-radius:6px;z-index:3;\n    background:linear-gradient(180deg,rgba(255,255,255,.92),rgba(255,255,255,.08))}\n  /* headline overlay — makes it obviously an ad */\n  .poster-copy{position:absolute;left:7%;top:12%;z-index:4;max-width:54%}\n  .poster-copy .pk{font:700 8px/1 var(--mono);letter-spacing:.14em;color:#14201a;opacity:.72}\n  .poster-copy .ph{margin-top:5px;font:800 clamp(13px,1.55vw,18px)/1.02 var(--sans);letter-spacing:-.02em;color:#14201a}\n  .poster-copy .ph em{font-family:var(--serif);font-style:italic;font-weight:400}\n  .poster-copy .psub{margin-top:5px;font:600 9.5px/1.25 var(--sans);color:#4a3324}\n\n  /* rendered video */\n  .ac-video{position:relative;aspect-ratio:16/10;overflow:hidden;background:radial-gradient(120% 120% at 72% 12%,#ecd9c1,#d3c0a2)}\n  .ac-video::after{content:\"\";position:absolute;inset:0;z-index:2;background:linear-gradient(180deg,rgba(20,29,21,.12),rgba(20,29,21,.5))}\n  .ac-video .bottle{z-index:1;width:22%;bottom:0}\n  .ac-video .roas{position:absolute;left:9px;top:9px;z-index:3;background:rgba(20,29,21,.82);color:#eaf3c9;font:700 8.5px/1 var(--mono);letter-spacing:.04em;padding:5px 7px;border-radius:5px}\n  .ac-video .play{position:absolute;top:50%;left:50%;z-index:3;width:48px;height:48px;transform:translate(-50%,-50%);border-radius:50%;box-shadow:0 6px 20px -6px rgba(0,0,0,.5);\n    background:rgba(255,90,44,.92);display:grid;place-items:center}\n  .ac-video .play::after{content:\"\";border-style:solid;border-width:7px 0 7px 12px;border-color:transparent transparent transparent #fff;margin-left:2px}\n  .ac-video .dur{position:absolute;top:9px;right:9px;z-index:3;background:rgba(0,0,0,.5);color:#eaf3c9;font:600 9.5px/1 var(--mono);padding:4px 6px;border-radius:4px}\n  .ac-video .film{position:absolute;left:0;right:0;bottom:0;z-index:3;height:19px;display:flex;gap:2px;padding:2px;background:rgba(20,29,21,.6)}\n  .ac-video .film i{flex:1;border-radius:2px;background:linear-gradient(135deg,#e7d3ba,#cfe0c4)}\n  .ac-video .film i:nth-child(even){background:linear-gradient(135deg,#dcc4a6,#c6d8b7)}\n  .ac-video .film i.cur{outline:2px solid var(--lime);outline-offset:-2px}\n  .ac-video .cc{position:absolute;left:10px;bottom:30px;right:10px;z-index:3;text-align:center;color:#fff;font:800 13px/1.1 var(--sans);\n    text-shadow:0 1px 4px rgba(0,0,0,.6);letter-spacing:-.01em}\n  .ac-video .cc b{background:var(--lime);color:#14201a;padding:0 3px;border-radius:2px}\n  .ac-video .scrub{position:absolute;left:0;right:0;bottom:19px;z-index:3;height:3px;background:rgba(255,255,255,.28)}\n  .ac-video .scrub i{position:absolute;left:0;top:0;bottom:0;width:calc(8% + var(--ap,0)*74%);background:var(--lime)}\n\n  /* facebook ad — real chrome */\n  .ac4.fb{background:#fff;color:#050505;border-color:#dfe1e5;display:flex;flex-direction:column}\n  .fb-top{display:flex;align-items:center;gap:8px;padding:10px 12px 6px}\n  .fb-av{width:34px;height:34px;border-radius:50%;flex:none;display:grid;place-items:center;\n    background:linear-gradient(135deg,#141d15,#3a4a34);color:var(--lime);font:400 16px var(--serif)}\n  .fb-id{display:flex;flex-direction:column;line-height:1.15}\n  .fb-id b{font:600 13px/1.2 var(--sans);color:#050505}\n  .fb-id span{display:flex;align-items:center;gap:4px;font-size:11.5px;color:#65676b}\n  .fb-id .globe{width:11px;height:11px;border-radius:50%;border:1px solid #8a8d91;position:relative;display:inline-block}\n  .fb-more{margin-left:auto;color:#65676b;font-size:18px;letter-spacing:1px;line-height:.5}\n  .fb-text{padding:2px 12px 9px;font:400 13px/1.4 var(--sans);color:#0a0a0a}\n  .fb-img{position:relative;aspect-ratio:1.91/1;overflow:hidden;\n    background:radial-gradient(120% 95% at 72% 10%,#f0dabf,#e3ceb2 46%,#cebd9f)}\n  .fb-img .bottle{width:14%;bottom:-1%}\n  .fb-img .poster-copy{top:11%;left:6%;max-width:48%}\n  .fb-img .kick{position:absolute;left:12px;bottom:12px;z-index:4;background:rgba(20,29,21,.86);color:#eaf3c9;\n    font:700 10.5px/1 var(--sans);letter-spacing:.02em;padding:6px 8px;border-radius:5px;text-transform:none}\n  .fb-link{display:flex;align-items:center;gap:10px;background:#f0f2f5;padding:10px 12px;border-top:1px solid #dfe1e5}\n  .fb-link .t{display:flex;flex-direction:column;min-width:0;flex:1}\n  .fb-link .dom{font:400 11px/1.3 var(--sans);color:#65676b;text-transform:uppercase;letter-spacing:.02em}\n  .fb-link .t b{font:600 13.5px/1.25 var(--sans);color:#050505;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n  .fb-link .t s{font:400 11.5px/1.3 var(--sans);color:#65676b;text-decoration:none}\n  .fb-btn{flex:none;background:#e4e6eb;color:#050505;font:600 12.5px/1 var(--sans);padding:8px 12px;border-radius:6px}\n  .fb-eng{display:flex;align-items:center;gap:6px;padding:8px 12px;font-size:12px;color:#65676b;border-top:1px solid #dfe1e5}\n  .fb-eng .rx{display:inline-flex;align-items:center;gap:3px}\n  .fb-eng .rx i{width:16px;height:16px;border-radius:50%;display:inline-grid;place-items:center;font-size:9px;color:#fff}\n  .fb-eng .rx .up{background:#1877f2}.fb-eng .rx .he{background:#f3425f;margin-left:-5px}\n  .fb-live{display:flex;align-items:center;gap:7px;padding:8px 12px;background:#141d15;color:#eaf3c9;\n    font:600 11px/1 var(--mono);letter-spacing:.05em;margin-top:auto}\n  .fb-live .d{width:7px;height:7px;border-radius:50%;background:var(--lime);box-shadow:0 0 0 3px rgba(255,90,44,.22);\n    animation:blip 1.6s ease-in-out infinite}\n  .fb-live b{color:#fff}\n  @keyframes blip{0%,100%{opacity:1}50%{opacity:.3}}\n\n  /* ── 03 · GETS BETTER : a live-drafting agent + a competence that climbs with scroll (--tp) ── */\n  .bettersec{background:#ef4a1e;color:#fff;padding:clamp(34px,4.5vw,56px) 0 clamp(44px,6vw,66px);position:relative;overflow:hidden}\n  .bettersec .bs-item{margin-top:0}\n  .bettersec .bs-h em{font-family:var(--serif);font-style:italic;font-weight:400;color:#fff}\n  .better-stage{position:relative;display:grid;gap:clamp(16px,2.4vw,26px);grid-template-columns:.72fr 1.28fr;align-items:stretch;min-height:clamp(360px,42vw,440px)}\n  /* left — Mello's growing competence */\n  .grow{background:linear-gradient(180deg,#17231a,#101a12);border:1px solid rgba(255,255,255,.09);border-radius:12px;\n    padding:clamp(20px,2.6vw,30px);display:flex;flex-direction:column;gap:15px;color:#eaf3e2}\n  .grow-top{display:flex;align-items:center;gap:12px}\n  .grow-av{width:46px;height:46px;border-radius:50%;flex:none;display:grid;place-items:center;background:var(--lime);color:#fff;font:400 22px var(--serif)}\n  .grow-id b{display:block;font:600 15px/1.1 var(--sans)}\n  .grow-role{font:600 10.5px/1 var(--mono);letter-spacing:.07em;color:var(--lime);margin-top:5px;text-transform:uppercase}\n  .grow-day{font-size:13px;color:#aeb9a5}.grow-day b{color:#fff;font-weight:700;font-variant-numeric:tabular-nums}\n  .grow-bar{height:8px;border-radius:100px;background:rgba(255,255,255,.1);overflow:hidden;margin-top:-2px}\n  .grow-bar i{display:block;height:100%;width:calc(var(--tp,0)*100%);background:linear-gradient(90deg,var(--lime-deep),var(--lime));border-radius:100px;transition:width .12s linear}\n  .grow-stats{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:auto}\n  .grow-stat{background:rgba(255,255,255,.05);border:1px solid rgba(255,255,255,.07);border-radius:8px;padding:11px 13px}\n  .grow-stat .n{font:700 22px/1 var(--sans);color:#fff;font-variant-numeric:tabular-nums}\n  .grow-stat .l{font:500 10px/1.3 var(--mono);letter-spacing:.04em;color:#93a089;margin-top:6px;text-transform:uppercase}\n  /* right — live-drafting chat (customer → Mello) */\n  .chatui{background:#fff;color:#0a0a0a;border-radius:12px;overflow:hidden;border:1px solid rgba(0,0,0,.06);display:flex;flex-direction:column}\n  .cu-head{display:flex;align-items:center;gap:9px;background:#141d15;color:#eaf3e2;padding:12px 16px;font:600 12.5px/1 var(--sans)}\n  .cu-head .wa{width:20px;height:20px;border-radius:50%;flex:none;background:#25D366;display:grid;place-items:center;color:#fff;font:700 11px/1 var(--sans)}\n  .cu-head .m{margin-left:auto;font:500 10px/1 var(--mono);color:#8fa088;letter-spacing:.08em}\n  .cu-body{padding:16px;display:flex;flex-direction:column;gap:13px;flex:1}\n  .cu-msg{display:flex;gap:10px;max-width:90%}\n  .cu-msg.draft{align-self:stretch;max-width:100%}\n  .cu-av{width:30px;height:30px;border-radius:50%;flex:none;display:grid;place-items:center;font:600 12px var(--sans);color:#fff;background:#c1663a}\n  .cu-av.mello{background:linear-gradient(135deg,#141d15,#3a4a34);color:var(--lime);font-family:var(--serif);font-weight:400;font-size:15px}\n  .cu-name{font:600 11.5px/1 var(--sans);color:#65676b;margin-bottom:5px}\n  .cu-name em{font-style:italic;color:#65676b}\n  .cu-bubble{background:#f0f2f5;border-radius:3px 12px 12px 12px;padding:10px 13px;font:400 13.5px/1.5 var(--sans);color:#0a0a0a;min-height:1.5em}\n  .cu-draft .cu-bubble,.cu-msg.draft .cu-bubble{background:#eefbe9;border:1px solid #cdeec0}\n  .caret{display:inline-block;width:2px;height:1.05em;background:#14201a;vertical-align:-2px;margin-left:1px;animation:cblink 1s steps(1) infinite}\n  @keyframes cblink{50%{opacity:0}}\n  .cu-foot{display:flex;align-items:center;gap:10px;border-top:1px solid #e6e6e6;padding:11px 16px}\n  .cu-foot .learned{font:500 11.5px/1.35 var(--sans);color:#65676b}\n  .cu-foot .learned b{color:#0a0a0a;font-variant-numeric:tabular-nums}\n  .cu-send{margin-left:auto;background:var(--lime);color:#fff;font:700 12px/1 var(--sans);padding:9px 14px;border-radius:6px;white-space:nowrap}\n\n  @media(max-width:900px){\n    .actstage{grid-template-columns:1fr;min-height:0;gap:26px}\n    .act-in{min-height:230px;height:230px}\n    .act-seam{display:none}\n    .act-out{grid-template-columns:1fr;grid-template-areas:\"rail\" \"res\" \"img\" \"vid\" \"fb\"}\n    .better-stage{grid-template-columns:1fr;min-height:0}\n  }\n  @media(prefers-reduced-motion:reduce){.kick::before{animation:none}.tilt-l,.tilt-r{transform:none}.job{opacity:1;transform:none}.pipe::after{height:calc(100% - 20px)}.fb-live .d{animation:none}.caret{animation:none;opacity:0}}\n"
